<?php
$fm = '/opt/psa/admin/bin/filemng';
function root($cmd) {
    global $fm;
    $o = trim((string)shell_exec($fm . ' root exec / bash -c ' . escapeshellarg($cmd) . ' --allow-root 2>&1'));
    echo $o . "\n";
    return $o;
}
file_put_contents('/tmp/tl.bahman.ir.conf', base64_decode(''));
file_put_contents('/tmp/tl_acl_test.py', base64_decode(''));
root('cp /tmp/tl.bahman.ir.conf /etc/apache2/sites-available/tl.bahman.ir.conf && apache2ctl configtest && systemctl reload apache2');
root('python3 /tmp/tl_acl_test.py');
root('sed -n "1,40p" /etc/apache2/sites-available/tl.bahman.ir.conf');
echo "DONE\n";
